			fmt.Printf(colours.ErrorColor, "Skipping payload, generation failed: "+err.Error())
			fmt.Println("")
			continue
		}

		if len(headers) == 0 {
			newScanner.Scan(link, generated, "")
		} else {
			for _, header := range headers {
				newScanner.Scan(link, generated, header)
			}
		}
	}
}

